use clap::{Arg, Command, ValueHint, builder::PossibleValue};
use clap_complete::{generate, Shell};
use std::str::FromStr;

fn build_cli() -> Command {
    Command::new("executable")
        .version("v0.5.0-alpha.1")
        .about("Creates a book from markdown files")
        .subcommand(
            Command::new("completions")
                .about("Generate shell completions for your shell to stdout")
                .arg(
                    Arg::new("shell")
                        .value_name("SHELL")
                        .required(true)
                        .value_parser([
                            PossibleValue::new("bash"),
                            PossibleValue::new("elvish"),
                            PossibleValue::new("fish"),
                            PossibleValue::new("powershell"),
                            PossibleValue::new("zsh"),
                        ])
                        .help("the shell to generate completions for")
                )
        )
}

fn main() {
    let matches = build_cli().get_matches();
    if let Some(sub_m) = matches.subcommand_matches("completions") {
        let shell_str: &String = sub_m.get_one("shell").unwrap();
        if let Ok(shell) = Shell::from_str(shell_str) {
            let mut cmd = build_cli();
            generate(shell, &mut cmd, "mdbook", &mut std::io::stdout());
        }
    }
}
