use serde::{Deserialize, Serialize};
use std::path::Path;

#[derive(Debug, Deserialize, Serialize, Clone)]
pub struct BookSection {
    pub title: Option<String>,
    pub authors: Option<Vec<String>>,
    pub description: Option<String>,
    pub src: Option<String>,
    pub language: Option<String>,
    #[serde(rename = "text-direction")]
    pub text_direction: Option<String>,
}

#[derive(Debug, Deserialize, Serialize, Clone)]
pub struct BuildSection {
    #[serde(rename = "build-dir")]
    pub build_dir: Option<String>,
    #[serde(rename = "create-missing")]
    pub create_missing: Option<bool>,
}

#[derive(Debug, Deserialize, Serialize, Clone, Default)]
pub struct Config {
    pub book: Option<BookSection>,
    pub build: Option<BuildSection>,
}

impl Config {
    pub fn from_file<P: AsRef<Path>>(path: P) -> Result<Self, String> {
        let content = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        toml::from_str(&content).map_err(|e| e.to_string())
    }

    pub fn title(&self) -> String {
        self.book.as_ref().and_then(|b| b.title.clone()).unwrap_or_default()
    }

    pub fn authors(&self) -> Vec<String> {
        self.book.as_ref().and_then(|b| b.authors.clone()).unwrap_or_default()
    }

    pub fn src(&self) -> String {
        self.book.as_ref().and_then(|b| b.src.clone()).unwrap_or_else(|| "src".to_string())
    }

    pub fn build_dir(&self) -> String {
        self.build.as_ref().and_then(|b| b.build_dir.clone()).unwrap_or_else(|| "book".to_string())
    }

    pub fn language(&self) -> String {
        self.book.as_ref().and_then(|b| b.language.clone()).unwrap_or_else(|| "en".to_string())
    }

    pub fn description(&self) -> String {
        self.book.as_ref().and_then(|b| b.description.clone()).unwrap_or_default()
    }
}
