    let mut items = Vec::new();
    let mut chapter_counters: Vec<usize> = Vec::new();

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        if trimmed.starts_with("# Summary") || trimmed.starts_with("# Table of Contents") {
            continue;
        }

        if trimmed == "---" {
            items.push(TocItem::Spacer);
            continue;
        }

        if trimmed.starts_with("# ") || trimmed.starts_with("## ") {
            let part_title = trimmed.trim_start_matches('#').trim().to_string();
            items.push(TocItem::PartTitle(part_title));
            chapter_counters.clear();
            continue;
        }

        if let Some((indent_level, title, link_target)) = parse_link_line(line) {
            let is_prefix = items.is_empty();
            let number = if !is_prefix {
                while chapter_counters.len() > indent_level + 1 {
                    chapter_counters.pop();
                }
                while chapter_counters.len() <= indent_level {
                    chapter_counters.push(0);
                }
                chapter_counters[indent_level] += 1;
                Some(format_number(&chapter_counters))
            } else {
                None
            };

            let (path_buf, html_path) = if let Some(target) = link_target {
                if target.is_empty() {
                    (None, None)
                } else {
                    let path = PathBuf::from(&target);
                    let html = target_to_html(&target);
                    (Some(path), Some(html))
                }
            } else {
                (None, None)
            };

            let chapter_content = if let Some(ref p) = path_buf {
                let full_path = src_dir.join(p);
                fs::read_to_string(&full_path).unwrap_or_default()
            } else {
                String::new()
            };

            let chapter = Chapter {
                title,
                path: path_buf,
                html_path,
                number,
                content: chapter_content,
                sub_items: Vec::new(),
            };

            if indent_level == 0 || items.is_empty() {
                items.push(TocItem::Chapter(chapter));
            } else {
                add_sub_item(&mut items, chapter, indent_level);
            }
        }
    }

    Ok(items)
}

fn parse_link_line(line: &str) -> Option<(usize, String, Option<String>)> {
    let spaces = line.chars().take_while(|c| c.is_whitespace()).count();
    let indent_level = spaces / 2;

    let trimmed = line.trim();
    let text = if trimmed.starts_with("- ") || trimmed.starts_with("* ") {
        trimmed[2..].trim()
    } else {
        trimmed
    };

    if let (Some(start_bracket), Some(end_bracket), Some(start_paren), Some(end_paren)) = 
        (text.find('['), text.find(']'), text.find('('), text.rfind(')')) {
        if start_bracket < end_bracket && end_bracket < start_paren && start_paren < end_paren {
            let title = text[start_bracket + 1..end_bracket].to_string();
            let target = text[start_paren + 1..end_paren].trim().to_string();
            return Some((indent_level, title, Some(target)));
        }
    } else if text.starts_with('[') && text.ends_with(']') {
        let title = text[1..text.len() - 1].to_string();
        return Some((indent_level, title, None));
    }

    None
}

fn target_to_html(target: &str) -> String {
    let path = target.split('#').next().unwrap_or(target);
    if path == "README.md" || path.ends_with("/README.md") || path == "index.md" || path.ends_with("/index.md") {
        let prefix = if path.contains('/') {
            let idx = path.rfind('/').unwrap();
            format!("{}/", &path[..idx])
        } else {
            String::new()
        };
        format!("{}index.html", prefix)
    } else if path.ends_with(".md") {
        format!("{}.html", &path[..path.len() - 3])
    } else {
        path.to_string()
    }
}

fn format_number(counters: &[usize]) -> String {
    let mut s = String::new();
    for c in counters.iter() {
        s.push_str(&c.to_string());
        s.push('.');
    }
    s
}

fn add_sub_item(items: &mut Vec<TocItem>, chapter: Chapter, level: usize) {
    if let Some(TocItem::Chapter(ref mut last_ch)) = items.last_mut() {
        if level == 1 {
            last_ch.sub_items.push(TocItem::Chapter(chapter));
        } else {
            add_sub_item(&mut last_ch.sub_items, chapter, level - 1);
        }
    } else {
        items.push(TocItem::Chapter(chapter));
    }
}
EOF"}

