pub fn slugify(text: &str) -> String {
    let mut slug = String::new();
    let mut last_was_dash = false;
    for c in text.to_lowercase().chars() {
        if c.is_alphanumeric() {
            slug.push(c);
            last_was_dash = false;
        } else if c == ' ' || c == '_' || c == '-' {
            if !last_was_dash && !slug.is_empty() {
                slug.push('-');
                last_was_dash = true;
            }
        }
    }
    slug.trim_end_matches('-').to_string()
}

pub fn render_markdown(md: &str) -> String {
    let mut html = String::new();
    let mut in_code_block = false;
    let mut code_lang = String::new();
    let mut code_buffer = String::new();

    for line in md.lines() {
        if line.starts_with("```") {
            if in_code_block {
                in_code_block = false;
                let escaped_code = html_escape(&code_buffer);
                if code_lang == "rust" || code_lang.starts_with("rust,") {
                    html.push_str("<pre><pre class=\"playground\"><code class=\"language-rust\">");
                    html.push_str(&escaped_code);
                    html.push_str("</code></pre></pre>\n");
                } else if !code_lang.is_empty() {
                    html.push_str("<pre><code class=\"language-");
                    html.push_str(&code_lang);
                    html.push_str("\">");
                    html.push_str(&escaped_code);
                    html.push_str("</code></pre>\n");
                } else {
                    html.push_str("<pre><code>");
                    html.push_str(&escaped_code);
                    html.push_str("</code></pre>\n");
                }
                code_buffer.clear();
            } else {
                in_code_block = true;
                code_lang = line.trim_start_matches('`').trim().to_string();
            }
            continue;
        }

        if in_code_block {
            code_buffer.push_str(line);
            code_buffer.push('\n');
            continue;
        }

        let trimmed = line.trim();
        if trimmed.starts_with('#') {
            let level = trimmed.chars().take_while(|&c| c == '#').count();
            if level >= 1 && level <= 6 {
                let text = trimmed[level..].trim();
                let slug = slugify(text);
                let text_html = render_inline(text);
                html.push_str(&format!(
                    "<h{} id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h{}>\n",
                    level, slug, slug, text_html, level
                ));
                continue;
            }
        }

        if trimmed.is_empty() {
            continue;
        }

        let line_html = render_inline(trimmed);
        html.push_str("<p>");
        html.push_str(&line_html);
        html.push_str("</p>\n");
    }

    html
}

fn html_escape(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

pub fn render_inline(text: &str) -> String {
    let mut result = String::new();
    let mut pos = 0;

    while pos < text.len() {
        if let Some(open_b) = text[pos..].find('[') {
            result.push_str(&text[pos..pos + open_b]);
            pos += open_b;

            if let Some(close_b) = text[pos..].find(']') {
                let link_text = &text[pos + 1..pos + close_b];
                let rest = &text[pos + close_b + 1..];
                if rest.starts_with('(') {
                    if let Some(close_p) = rest.find(')') {
                        let link_target = &rest[1..close_p];
                        let rewritten_target = rewrite_link(link_target);
                        result.push_str(&format!("<a href=\"{}\">{}</a>", rewritten_target, html_escape(link_text)));
                        pos += close_b + 1 + close_p + 1;
                        continue;
                    }
                }
            }
            result.push('[');
            pos += 1;
        } else {
            result.push_str(&text[pos..]);
            break;
        }
    }

    result
}

fn rewrite_link(target: &str) -> String {
    if target.starts_with("http://") || target.starts_with("https://") || target.starts_with("mailto:") || target.starts_with('#') {
        return target.to_string();
    }
    let parts: Vec<&str> = target.split('#').collect();
    let file = parts[0];
    let fragment = if parts.len() > 1 {
        format!("#{}", parts[1])
    } else {
        String::new()
    };

    let new_file = if file == "README.md" || file.ends_with("/README.md") || file == "index.md" || file.ends_with("/index.md") {
        let prefix = if file.contains('/') {
            let idx = file.rfind('/').unwrap();
            format!("{}/", &file[..idx])
        } else {
            String::new()
        };
        format!("{}index.html", prefix)
    } else if file.ends_with(".md") {
        format!("{}.html", &file[..file.len() - 3])
    } else {
        file.to_string()
    };

    format!("{}{}", new_file, fragment)
}
