            io::stdout().flush().ok();
            let mut input = String::new();
            io::stdin().read_line(&mut input).ok();
            if input.trim().eq_ignore_ascii_case("y") || input.trim().eq_ignore_ascii_case("yes") {
                create_gitignore = true;
            }
        }

        if book_title.is_none() && is_tty {
            print!("What title would you like to give the book? ");
            io::stdout().flush().ok();
            let mut input = String::new();
            io::stdin().read_line(&mut input).ok();
            let trimmed = input.trim();
            if !trimmed.is_empty() {
                book_title = Some(trimmed.to_string());
            }
        }
    }

    if theme {
        let theme_dir = target_dir.join("theme");
        println!("\nCopying the default theme to {}", theme_dir.display());
        fs::create_dir_all(&theme_dir).map_err(|e| e.to_string())?;
        for (rel_path, bytes) in assets::get_theme_files() {
            let dest = theme_dir.join(rel_path);
            if let Some(parent) = dest.parent() {
                fs::create_dir_all(parent).ok();
            }
            fs::write(dest, bytes).ok();
        }
    }

    let book_toml_path = target_dir.join("book.toml");
    let author = get_git_user().unwrap_or_else(|| "Author".to_string());

    let mut toml_content = String::from("[book]\n");
    toml_content.push_str(&format!("authors = [\"{}\"]\n", author));
    toml_content.push_str("language = \"en\"\n");
    toml_content.push_str("src = \"src\"\n");
    if let Some(ref t) = book_title {
        toml_content.push_str(&format!("title = \"{}\"\n", t));
    }
