    fs::create_dir_all(&src_dir).map_err(|e| e.to_string())?;

    let summary_path = src_dir.join("SUMMARY.md");
    if !summary_path.exists() {
        fs::write(&summary_path, "# Summary\n\n- [Chapter 1](./chapter_1.md)\n").map_err(|e| e.to_string())?;
    }

    let ch1_path = src_dir.join("chapter_1.md");
    if !ch1_path.exists() {
        fs::write(&ch1_path, "# Chapter 1\n").map_err(|e| e.to_string())?;
    }

    if create_gitignore {
        let gitignore_path = target_dir.join(".gitignore");
        if !gitignore_path.exists() {
            fs::write(&gitignore_path, "book\n").map_err(|e| e.to_string())?;
        }
    }

    let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
    println!("{} [INFO] (mdbook_driver::init): Creating a new book with stub content", now);
    println!("\nAll done, no errors...");

    Ok(())
}

fn get_git_user() -> Option<String> {
    let output = Command::new("git").args(["config", "user.name"]).output().ok()?;
    if output.status.success() {
        let name = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if !name.is_empty() {
            return Some(name);
        }
    }
    None
}
EOF"}

