use std::fs;
use std::path::Path;
use crate::config::Config;

pub fn execute(dir: Option<&str>, dest_dir: Option<&str>) -> Result<(), String> {
    let root_dir = Path::new(dir.unwrap_or("."));

    let config = if root_dir.join("book.toml").is_file() {
        Config::from_file(root_dir.join("book.toml")).unwrap_or_default()
    } else {
        Config::default()
    };

    let src_dir = root_dir.join(config.src());
    let summary_path = src_dir.join("SUMMARY.md");

    if !summary_path.is_file() {
        let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
        eprintln!("{} [ERROR] (mdbook_core::utils): Error: Couldn't open SUMMARY.md in \"{}\" directory", now, src_dir.display());
        eprintln!("{} [ERROR] (mdbook_core::utils): \tCaused By: No such file or directory (os error 2)", now);
        std::process::exit(101);
    }

    let target_dest = if let Some(d) = dest_dir {
        Path::new(d).to_path_buf()
    } else {
        root_dir.join(config.build_dir())
    };

    if target_dest.exists() {
        let (file_count, dir_count, total_bytes) = count_dir_contents(&target_dest);
        fs::remove_dir_all(&target_dest).map_err(|e| e.to_string())?;

        if file_count > 0 {
            let file_str = if file_count == 1 { "file" } else { "files" };
            println!("Removed {} {}, {}B total", file_count, file_str, total_bytes);
        } else if dir_count > 0 {
            let dir_str = if dir_count == 1 { "directory" } else { "directories" };
            println!("Removed {} {}, {}B total", dir_count, dir_str, total_bytes);
        } else {
            println!("Removed 0 files");
        }
    } else {
        println!("Removed 0 files");
    }

    Ok(())
}

fn count_dir_contents(path: &Path) -> (usize, usize, u64) {
    let mut files = 0;
    let mut dirs = 0;
    let mut bytes = 0;

    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries.flatten() {
            let p = entry.path();
            if p.is_dir() {
                dirs += 1;
                let (f, d, b) = count_dir_contents(&p);
                files += f;
                dirs += d;
                bytes += b;
            } else if p.is_file() {
                files += 1;
                if let Ok(meta) = entry.metadata() {
                    bytes += meta.len();
                }
            }
        }
    }

    (files, dirs, bytes)
}
EOF"}

