use std::path::Path;
use std::process::Command;
use crate::config::Config;
use crate::renderer;
use crate::summary::parse_summary;

pub fn execute(dir: Option<&str>, dest_dir: Option<&str>, open_browser: bool) -> Result<(), String> {
    let root_dir = Path::new(dir.unwrap_or("."));

    let config_path = root_dir.join("book.toml");
    let config = if config_path.is_file() {
        match Config::from_file(&config_path) {
            Ok(c) => c,
            Err(e) => {
                let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
                eprintln!("{} [ERROR] (mdbook_core::utils): Error: Invalid configuration file", now);
                eprintln!("{} [ERROR] (mdbook_core::utils): \tCaused By: {}", now, e);
                std::process::exit(101);
            }
        }
    } else {
        Config::default()
    };

    let src_dir = root_dir.join(config.src());
    let summary_path = src_dir.join("SUMMARY.md");

    if !summary_path.is_file() {
        let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
        eprintln!("{} [ERROR] (mdbook_core::utils): Error: Couldn't open SUMMARY.md in \"{}\" directory", now, src_dir.display());
        eprintln!("{} [ERROR] (mdbook_core::utils): \tCaused By: No such file or directory (os error 2)", now);
        std::process::exit(101);
    }

    let toc_items = match parse_summary(&summary_path, &src_dir) {
        Ok(items) => items,
        Err(e) => {
            let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
            eprintln!("{} [ERROR] (mdbook_core::utils): Error: {}", now, e);
            std::process::exit(101);
        }
    };

    let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
    println!("{} [INFO] (mdbook_driver::mdbook): Book building has started", now);

    let target_dest = if let Some(d) = dest_dir {
        Path::new(d).to_path_buf()
    } else {
        root_dir.join(config.build_dir())
    };

    renderer::render_book(root_dir, &config, &toc_items, &target_dest)?;

    let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
    println!("{} [INFO] (mdbook_driver::mdbook): Running the html backend", now);
    println!("{} [INFO] (mdbook_html::html_handlebars::hbs_renderer): HTML book written to `{}`", now, target_dest.display());

    if open_browser {
        let index_html = target_dest.join("index.html");
        let _ = Command::new("xdg-open").arg(&index_html).spawn().or_else(|_| {
            Command::new("open").arg(&index_html).spawn()
        });
    }

    Ok(())
}
EOF"}

