{"command":"cat << 'EOF' > src/cmd/test_cmd.rs
use std::path::Path;
use std::process::Command;
use walkdir::WalkDir;
use crate::config::Config;
use crate::summary::parse_summary;

pub fn execute(
    dir: Option<&str>,
    dest_dir: Option<&str>,
    chapter: Option<&str>,
    library_path: Option<&str>,
) -> Result<(), String> {
    let root_dir = Path::new(dir.unwrap_or("."));

    let config_path = root_dir.join("book.toml");
    let config = if config_path.is_file() {
        Config::from_file(&config_path).unwrap_or_default()
    } else {
        Config::default()
    };

    let src_dir = root_dir.join(config.src());
    let summary_path = src_dir.join("SUMMARY.md");

    if !summary_path.is_file() {
        let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
        eprintln!("{} [ERROR] (mdbook_core::utils): Error: Couldn't open SUMMARY.md in \"{}\" directory", now, src_dir.display());
        eprintln!("{} [ERROR] (mdbook_core::utils): \tCaused By: No such file or directory (os error 2)", now);
        std::process::exit(101);
    }

    let _ = parse_summary(&summary_path, &src_dir);

    let mut failed = false;

    for entry in WalkDir::new(&src_dir).into_iter().flatten() {
        let p = entry.path();
        if p.is_file() && p.extension().map_or(false, |ext| ext == "md") {
            let rel_path = p.strip_prefix(&src_dir).unwrap_or(p);

            if let Some(ch) = chapter {
                if !rel_path.to_string_lossy().contains(ch) {
                    continue;
                }
            }

            let title = p.file_stem().and_then(|s| s.to_str()).unwrap_or("Chapter");
            let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
            println!("{} [INFO] (mdbook_driver::mdbook): Testing chapter '{}': \"{}\"", now, title, rel_path.display());

            let mut rustdoc = Command::new("rustdoc");
            rustdoc.arg("--test").arg(p);

            if let Some(lib_p) = library_path {
                for l in lib_p.split(',') {
                    rustdoc.arg("-L").arg(l.trim());
                }
            }

            let output = match rustdoc.output() {
                Ok(o) => o,
                Err(e) => {
                    eprintln!("Error executing rustdoc: {}", e);
                    std::process::exit(101);
                }
            };

            if !output.status.success() {
                failed = true;
                println!("{}", String::from_utf8_lossy(&output.stdout));
                eprintln!("{}", String::from_utf8_lossy(&output.stderr));
            }
        }
    }

    if failed {
        let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
        eprintln!("{} [ERROR] (mdbook_core::utils): Error: One or more tests failed", now);
        std::process::exit(101);
    }

    Ok(())
}
EOF"}

