{"command":"cat << 'EOF' > src/cmd/serve.rs
use std::path::Path;
use std::thread;
use std::time::Duration;
use crate::cmd::build;
use crate::config::Config;

pub fn execute(
    dir: Option<&str>,
    dest_dir: Option<&str>,
    hostname: Option<&str>,
    port: u16,
    open_browser: bool,
    _watcher: Option<&str>,
) -> Result<(), String> {
    build::execute(dir, dest_dir, open_browser)?;

    let host = hostname.unwrap_or("localhost");

    let now = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
    println!("{} [INFO] (mdbook::cmd::serve): Serving on: http://{}:{}", now, host, port);
    println!("{} [INFO] (mdbook::cmd::watch::poller): Watching for changes...", now);

    let root_dir = Path::new(dir.unwrap_or(".")).to_path_buf();
    let config = Config::from_file(root_dir.join("book.toml")).unwrap_or_default();
    let target_dest = if let Some(d) = dest_dir {
        Path::new(d).to_path_buf()
    } else {
        root_dir.join(config.build_dir())
    };

    // Simple HTTP file server thread
    let server_dest = target_dest.clone();
    let listen_addr = format!("{}:{}", host, port);

    thread::spawn(move || {
        let sys = std::process::Command::new("python3")
            .args(["-m", "http.server", &port.to_string(), "--directory", &server_dest.to_string_lossy(), "--bind", host])
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status();
    });

    loop {
        thread::sleep(Duration::from_secs(1));
    }
}
EOF"}

