use std::fs;
use std::path::{Path, PathBuf};
use crate::assets;
use crate::config::Config;
use crate::markdown::{process_includes, render_markdown};
use crate::summary::{Chapter, TocItem};

pub fn render_book(root_dir: &Path, config: &Config, toc_items: &[TocItem], dest_dir: &Path) -> Result<(), String> {
    fs::create_dir_all(dest_dir).map_err(|e| e.to_string())?;

    // Copy static theme assets
    let custom_theme_dir = root_dir.join("theme");
    let static_assets = assets::get_book_static_assets();
    for (rel_path, bytes) in static_assets {
        let target_path = dest_dir.join(rel_path);
        if let Some(parent) = target_path.parent() {
            fs::create_dir_all(parent).ok();
        }

        let custom_file = custom_theme_dir.join(rel_path);
        if custom_file.is_file() {
            fs::copy(&custom_file, &target_path).ok();
        } else {
            fs::write(&target_path, bytes).ok();
        }
    }

    // Write .nojekyll
    fs::write(dest_dir.join(".nojekyll"), "").ok();

    // Flatten chapters for navigation
    let mut chapters = Vec::new();
    collect_chapters(toc_items, &mut chapters);

    // Build TOC HTML and JS
    let toc_inner_html = build_toc_html(toc_items, false);
    let toc_iframe_html = build_toc_html(toc_items, true);

    let toc_js_content = format!(
        concat!(
            "class MDBookSidebarScrollbox extends HTMLElement {{\n",
            "    constructor() {{\n",
            "        super();\n",
            "    }}\n",
            "    connectedCallback() {{\n",
            "        this.innerHTML = '{}';\n",
            "        let current_page = document.location.href.toString().split(\"#\")[0].split(\"?\")[0];\n",
            "        if (current_page.endsWith(\"/\")) {{\n",
            "            current_page += \"index.html\";\n",
            "        }}\n",
            "        var links = Array.prototype.slice.call(this.querySelectorAll(\"a\"));\n",
            "        var l = links.length;\n",
            "        for (var i = 0; i < l; ++i) {{\n",
            "            var link = links[i];\n",
            "            var href = link.getAttribute(\"href\");\n",
            "            if (href && !href.startsWith(\"#\") && !/^(?:[a-z+]+:)?\\/\\//.test(href)) {{\n",
            "                link.href = path_to_root + href;\n",
            "            }}\n",
            "            if (link.href === current_page || (i === 0 && path_to_root === \"\" && current_page.endsWith(\"/index.html\"))) {{\n",
            "                link.classList.add(\"active\");\n",
            "                var parent = link.parentElement;\n",
            "                if (parent && parent.classList.contains(\"chapter-item\")) {{\n",
            "                    parent.classList.add(\"expanded\");\n",
            "                }}\n",
            "                while (parent) {{\n",
            "                    if (parent.tagName === \"LI\" && parent.previousElementSibling) {{\n",
            "                        if (parent.previousElementSibling.classList.contains(\"chapter-item\")) {{\n",
            "                            parent.previousElementSibling.classList.add(\"expanded\");\n",
            "                        }}\n",
            "                    }}\n",
            "                    parent = parent.parentElement;\n",
            "                }}\n",
            "            }}\n",
            "        }}\n",
            "        this.addEventListener('click', function(e) {{\n",
            "            if (e.target.tagName === 'A') {{\n",
            "                sessionStorage.setItem('sidebar-scroll', this.scrollTop);\n",
            "            }}\n",
            "        }}, {{ passive: true }});\n",
            "        var sidebarScrollTop = sessionStorage.getItem('sidebar-scroll');\n",
            "        sessionStorage.removeItem('sidebar-scroll');\n",
            "        if (sidebarScrollTop) {{\n",
            "            this.scrollTop = sidebarScrollTop;\n",
            "        }} else {{\n",
            "            var activeSection = document.querySelector('#sidebar .active');\n",
            "            if (activeSection) {{\n",
            "                activeSection.scrollIntoView({{ block: 'center' }});\n",
            "            }}\n",
            "        }}\n",
            "        var sidebarAnchorToggles = document.querySelectorAll('#sidebar a.toggle');\n",
            "        function toggleSection(ev) {{\n",
            "            ev.currentTarget.parentElement.classList.toggle('expanded');\n",
            "        }}\n",
            "        Array.from(sidebarAnchorToggles).forEach(function (el) {{\n",
            "            el.addEventListener('click', toggleSection);\n",
            "        }});\n",
            "    }}\n",
            "}}\n",
            "window.customElements.define(\"mdbook-sidebar-scrollbox\", MDBookSidebarScrollbox);"
        ),
        toc_inner_html.replace('\'', "\\'")
    );

    fs::write(dest_dir.join("toc.js"), toc_js_content).ok();

    let toc_html_page = format!(
        concat!(
            "<!DOCTYPE HTML>\n",
            "<html lang=\"en\" class=\"light\" dir=\"ltr\">\n",
            "    <head>\n",
            "        <meta charset=\"UTF-8\">\n",
            "        <meta name=\"robots\" content=\"noindex\">\n",
            "        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n",
            "        <meta name=\"theme-color\" content=\"#ffffff\">\n",
            "        <link rel=\"stylesheet\" href=\"css/variables.css\">\n",
            "        <link rel=\"stylesheet\" href=\"css/general.css\">\n",
            "        <link rel=\"stylesheet\" href=\"css/chrome.css\">\n",
            "        <link rel=\"stylesheet\" href=\"css/print.css\" media=\"print\">\n",
            "        <link rel=\"stylesheet\" href=\"FontAwesome/css/font-awesome.css\">\n",
            "        <link rel=\"stylesheet\" href=\"fonts/fonts.css\">\n",
            "    </head>\n",
            "    <body class=\"sidebar-iframe-inner\">\n",
            "        {}\n",
            "    </body>\n",
            "</html>"
        ),
        toc_iframe_html
    );

    fs::write(dest_dir.join("toc.html"), toc_html_page).ok();

    let template = assets::INDEX_HBS;
    let src_dir = root_dir.join(config.src());

    let mut print_content = String::new();

    for (idx, ch) in chapters.iter().enumerate() {
        let raw_md = process_includes(&ch.content, &src_dir);
        let chapter_html = render_markdown(&raw_md);

        print_content.push_str(&chapter_html);
        print_content.push_str("\n<div style=\"break-before: page; page-break-before: always;\"></div>\n");

        if let Some(ref html_rel_path) = ch.html_path {
            let page_dest = dest_dir.join(html_rel_path);
            if let Some(parent) = page_dest.parent() {
                fs::create_dir_all(parent).ok();
            }

            let depth = Path::new(html_rel_path).components().count().saturating_sub(1);
            let path_to_root = if depth == 0 {
                String::new()
            } else {
                "../".repeat(depth)
            };

            let prev_link = if idx > 0 {
                chapters[idx - 1].html_path.clone()
            } else {
                None
            };

            let next_link = if idx + 1 < chapters.len() {
                chapters[idx + 1].html_path.clone()
            } else {
                None
            };

            let rendered_page = render_template(
                template,
                config,
                &ch.title,
                &chapter_html,
                &path_to_root,
                prev_link.as_deref(),
                next_link.as_deref(),
                false,
            );

            fs::write(&page_dest, rendered_page).ok();

            if idx == 0 && html_rel_path != "index.html" {
                fs::write(dest_dir.join("index.html"), render_template(
                    template,
                    config,
                    &ch.title,
                    &chapter_html,
                    "",
                    None,
                    next_link.as_deref(),
                    false,
                )).ok();
            }
        }
    }

    let not_found_md = src_dir.join("404.md");
    let not_found_html = if not_found_md.is_file() {
        let content = fs::read_to_string(&not_found_md).unwrap_or_default();
        render_markdown(&process_includes(&content, &src_dir))
    } else {
        "<h1 id=\"document-not-found-404\"><a class=\"header\" href=\"#document-not-found-404\">Document not found (404)</a></h1>\n<p>This URL is invalid, sorry. Please use the navigation bar or search to continue.</p>\n".to_string()
    };

    fs::write(
        dest_dir.join("404.html"),
        render_template(template, config, "404 - Document not found", &not_found_html, "", None, None, false),
    ).ok();

    fs::write(
        dest_dir.join("print.html"),
        render_template(template, config, &config.title(), &print_content, "", None, None, true),
    ).ok();

    let search_index_js = "window.search = Object.assign(window.search, JSON.parse('{\"doc_urls\":[],\"index\":{\"documentStore\":{\"docInfo\":{},\"docs\":{},\"length\":0,\"save\":true},\"fields\":[\"title\",\"body\",\"breadcrumbs\"],\"index\":{\"body\":{\"root\":{}},\"breadcrumbs\":{\"root\":{}},\"title\":{\"root\":{}}},\"lang\":\"English\",\"pipeline\":[\"trimmer\",\"stopWordFilter\",\"stemmer\"],\"ref\":\"id\",\"version\":\"0.9.5\"},\"results_options\":{\"limit_results\":30,\"teaser_word_count\":30},\"search_options\":{\"bool\":\"OR\",\"expand\":true,\"fields\":{\"body\":{\"boost\":1},\"breadcrumbs\":{\"boost\":1},\"title\":{\"boost\":2}}}}'));";
    fs::write(dest_dir.join("searchindex.js"), search_index_js).ok();

    Ok(())
}

fn collect_chapters<'a>(toc_items: &'a [TocItem], chapters: &mut Vec<&'a Chapter>) {
    for item in toc_items {
        if let TocItem::Chapter(ch) = item {
            chapters.push(ch);
            collect_chapters(&ch.sub_items, chapters);
        }
    }
}

fn build_toc_html(items: &[TocItem], iframe: bool) -> String {
    let mut html = String::from("<ol class=\"chapter\">");
    for item in items {
        match item {
            TocItem::Chapter(ch) => {
                let target_attr = if iframe { " target=\"_parent\"" } else { "" };
                let link_path = ch.html_path.as_deref().unwrap_or("#");
                let num_span = if let Some(ref num) = ch.number {
                    format!("<strong aria-hidden=\"true\">{}</strong> ", num)
                } else {
                    String::new()
                };
                let affix_class = if ch.number.is_none() { "affix " } else { "" };

                html.push_str(&format!(
                    "<li class=\"chapter-item expanded {}\"><a href=\"{}\"{}>{}{}</a></li>",
                    affix_class, link_path, target_attr, num_span, ch.title
                ));

                if !ch.sub_items.is_empty() {
                    html.push_str("<li><ol class=\"section\">");
                    html.push_str(&build_toc_inner(&ch.sub_items, iframe));
                    html.push_str("</ol></li>");
                }
            }
            TocItem::PartTitle(title) => {
                html.push_str(&format!("<li class=\"chapter-item expanded affix \"><li class=\"part-title\">{}</li>", title));
            }
            TocItem::Spacer => {
                html.push_str("<li class=\"chapter-item expanded affix \"><li class=\"spacer\"></li>");
            }
        }
    }
    html.push_str("</ol>");
    html
}

fn build_toc_inner(items: &[TocItem], iframe: bool) -> String {
    let mut html = String::new();
    for item in items {
        if let TocItem::Chapter(ch) = item {
            let target_attr = if iframe { " target=\"_parent\"" } else { "" };
            let link_path = ch.html_path.as_deref().unwrap_or("#");
            let num_span = if let Some(ref num) = ch.number {
                format!("<strong aria-hidden=\"true\">{}</strong> ", num)
            } else {
                String::new()
            };
            let affix_class = if ch.number.is_none() { "affix " } else { "" };

            html.push_str(&format!(
                "<li class=\"chapter-item expanded {}\"><a href=\"{}\"{}>{}{}</a></li>",
                affix_class, link_path, target_attr, num_span, ch.title
            ));

            if !ch.sub_items.is_empty() {
                html.push_str("<li><ol class=\"section\">");
                html.push_str(&build_toc_inner(&ch.sub_items, iframe));
                html.push_str("</ol></li>");
            }
        }
    }
    html
}

fn render_template(
    template: &str,
    config: &Config,
    page_title: &str,
    content: &str,
    path_to_root: &str,
    prev_link: Option<&str>,
    next_link: Option<&str>,
    is_print: bool,
) -> String {
    let mut result = template.to_string();

    result = result.replace("{{ language }}", &config.language());
    result = result.replace("{{ default_theme }}", "light");
    result = result.replace("{{ preferred_dark_theme }}", "navy");
    result = result.replace("{{ text_direction }}", "ltr");
    result = result.replace("{{ title }}", page_title);
    result = result.replace("{{ description }}", &config.description());
    result = result.replace("{{ path_to_root }}", path_to_root);
    result = result.replace("{{{ content }}}", content);

    result = replace_resource_helper(&result, path_to_root);

    result = replace_if_block(&result, "is_print", is_print);
    result = replace_if_block(&result, "favicon_svg", true);
    result = replace_if_block(&result, "favicon_png", true);
    result = replace_if_block(&result, "print_enable", true);
    result = replace_if_block(&result, "copy_fonts", true);
    result = replace_if_block(&result, "search_js", true);
    result = replace_if_block(&result, "search_enabled", true);
    result = replace_if_block(&result, "playground_line_numbers", false);
    result = replace_if_block(&result, "playground_copyable", true);
    result = replace_if_block(&result, "playground_js", false);
    result = replace_if_block(&result, "mathjax_support", false);
    result = replace_if_block(&result, "live_reload_endpoint", false);
    result = replace_if_block(&result, "fragment_map", false);
    result = replace_if_block(&result, "base_url", false);

    result = remove_handlebars_blocks(&result);

    result = render_nav_block(&result, "previous", prev_link, path_to_root);
    result = render_nav_block(&result, "next", next_link, path_to_root);

    result
}

fn replace_resource_helper(template: &str, path_to_root: &str) -> String {
    let mut out = template.to_string();
    while let Some(start) = out.find("{{ resource \"") {
        if let Some(end) = out[start..].find("\" }}") {
            let res = out[start + "{{ resource \"".len()..start + end].to_string();
            let full_res = format!("{}{}", path_to_root, res);
            out.replace_range(start..start + end + "\" }}".len(), &full_res);
        } else {
            break;
        }
    }
    out
}

fn replace_if_block(template: &str, var_name: &str, condition: bool) -> String {
    let open_tag = format!("{{{{#if {}}}}}", var_name);
    let close_tag = "{{/if}}";

    let mut out = template.to_string();
    while let Some(start) = out.find(&open_tag) {
        if let Some(end) = out[start..].find(close_tag) {
            let inner = out[start + open_tag.len()..start + end].to_string();
            if condition {
                out.replace_range(start..start + end + close_tag.len(), &inner);
            } else {
                out.replace_range(start..start + end + close_tag.len(), "");
            }
        } else {
            break;
        }
    }
    out
}

fn render_nav_block(template: &str, block_name: &str, link: Option<&str>, path_to_root: &str) -> String {
    let open_tag = format!("{{{{#{}}}}}", block_name);
    let close_tag = format!("{{{{/{}}}}}", block_name);

    let mut out = template.to_string();
    while let Some(start) = out.find(&open_tag) {
        if let Some(end) = out[start..].find(&close_tag) {
            if let Some(l) = link {
                let inner = out[start + open_tag.len()..start + end].to_string();
                let rendered = inner.replace("{{link}}", l).replace("{{ path_to_root }}", path_to_root);
                out.replace_range(start..start + end + close_tag.len(), &rendered);
            } else {
                out.replace_range(start..start + end + close_tag.len(), "");
            }
        } else {
            break;
        }
    }
    out
}

fn remove_handlebars_blocks(template: &str) -> String {
    let mut out = template.to_string();
    for tag in &["{{> head}}", "{{#each additional_css}}", "{{/each}}", "{{#each additional_js}}"] {
        out = out.replace(tag, "");
    }
    out
}
EOF"}

