    ).ok();

    fs::write(
        dest_dir.join("print.html"),
        render_template(template, config, &config.title(), &print_content, "", None, None, true),
    ).ok();

    let search_index_js = "window.search = Object.assign(window.search, JSON.parse('{\"doc_urls\":[],\"index\":{\"documentStore\":{\"docInfo\":{},\"docs\":{},\"length\":0,\"save\":true},\"fields\":[\"title\",\"body\",\"breadcrumbs\"],\"index\":{\"body\":{\"root\":{}},\"breadcrumbs\":{\"root\":{}},\"title\":{\"root\":{}}},\"lang\":\"English\",\"pipeline\":[\"trimmer\",\"stopWordFilter\",\"stemmer\"],\"ref\":\"id\",\"version\":\"0.9.5\"},\"results_options\":{\"limit_results\":30,\"teaser_word_count\":30},\"search_options\":{\"bool\":\"OR\",\"expand\":true,\"fields\":{\"body\":{\"boost\":1},\"breadcrumbs\":{\"boost\":1},\"title\":{\"boost\":2}}}}'));";
    fs::write(dest_dir.join("searchindex.js"), search_index_js).ok();

    Ok(())
}

fn collect_chapters<'a>(toc_items: &'a [TocItem], chapters: &mut Vec<&'a Chapter>) {
    for item in toc_items {
        if let TocItem::Chapter(ch) = item {
            chapters.push(ch);
            collect_chapters(&ch.sub_items, chapters);
        }
    }
}

fn build_toc_html(items: &[TocItem], iframe: bool) -> String {
    let mut html = String::from("<ol class=\"chapter\">");
    for item in items {
        match item {
            TocItem::Chapter(ch) => {
                let target_attr = if iframe { " target=\"_parent\"" } else { "" };
                let link_path = ch.html_path.as_deref().unwrap_or("#");
                let num_span = if let Some(ref num) = ch.number {
                    format!("<strong aria-hidden=\"true\">{}</strong> ", num)
                } else {
                    String::new()
                };
                let affix_class = if ch.number.is_none() { "affix " } else { "" };

                html.push_str(&format!(
                    "<li class=\"chapter-item expanded {}\"><a href=\"{}\"{}>{}{}</a></li>",
                    affix_class, link_path, target_attr, num_span, ch.title
                ));

                if !ch.sub_items.is_empty() {
                    html.push_str("<li><ol class=\"section\">");
                    html.push_str(&build_toc_inner(&ch.sub_items, iframe));
                    html.push_str("</ol></li>");
                }
            }
            TocItem::PartTitle(title) => {
                html.push_str(&format!("<li class=\"chapter-item expanded affix \"><li class=\"part-title\">{}</li>", title));
            }
            TocItem::Spacer => {
                html.push_str("<li class=\"chapter-item expanded affix \"><li class=\"spacer\"></li>");
            }
        }
    }
    html.push_str("</ol>");
    html
}

fn build_toc_inner(items: &[TocItem], iframe: bool) -> String {
    let mut html = String::new();
    for item in items {
        if let TocItem::Chapter(ch) = item {
            let target_attr = if iframe { " target=\"_parent\"" } else { "" };
            let link_path = ch.html_path.as_deref().unwrap_or("#");
            let num_span = if let Some(ref num) = ch.number {
                format!("<strong aria-hidden=\"true\">{}</strong> ", num)
            } else {
                String::new()
            };
            let affix_class = if ch.number.is_none() { "affix " } else { "" };

            html.push_str(&format!(
                "<li class=\"chapter-item expanded {}\"><a href=\"{}\"{}>{}{}</a></li>",
                affix_class, link_path, target_attr, num_span, ch.title
            ));

            if !ch.sub_items.is_empty() {
                html.push_str("<li><ol class=\"section\">");
                html.push_str(&build_toc_inner(&ch.sub_items, iframe));
                html.push_str("</ol></li>");
            }
        }
    }
    html
}

fn render_template(
    template: &str,
    config: &Config,
    page_title: &str,
    content: &str,
    path_to_root: &str,
    prev_link: Option<&str>,
    next_link: Option<&str>,
    is_print: bool,
) -> String {
    let mut result = template.to_string();

    result = result.replace("{{ language }}", &config.language());
    result = result.replace("{{ default_theme }}", "light");
    result = result.replace("{{ preferred_dark_theme }}", "navy");
    result = result.replace("{{ text_direction }}", "ltr");
    result = result.replace("{{ title }}", page_title);
    result = result.replace("{{ description }}", &config.description());
    result = result.replace("{{ path_to_root }}", path_to_root);
    result = result.replace("{{{ content }}}", content);

    result = replace_resource_helper(&result, path_to_root);

    result = replace_if_block(&result, "is_print", is_print);
    result = replace_if_block(&result, "favicon_svg", true);
    result = replace_if_block(&result, "favicon_png", true);
    result = replace_if_block(&result, "print_enable", true);
    result = replace_if_block(&result, "copy_fonts", true);
    result = replace_if_block(&result, "search_js", true);
    result = replace_if_block(&result, "search_enabled", true);
    result = replace_if_block(&result, "playground_line_numbers", false);
    result = replace_if_block(&result, "playground_copyable", true);
    result = replace_if_block(&result, "playground_js", false);
    result = replace_if_block(&result, "mathjax_support", false);
    result = replace_if_block(&result, "live_reload_endpoint", false);
    result = replace_if_block(&result, "fragment_map", false);
    result = replace_if_block(&result, "base_url", false);

    result = remove_handlebars_blocks(&result);

    result = render_nav_block(&result, "previous", prev_link, path_to_root);
    result = render_nav_block(&result, "next", next_link, path_to_root);

    result
}

fn replace_resource_helper(template: &str, path_to_root: &str) -> String {
    let mut out = template.to_string();
    while let Some(start) = out.find("{{ resource \"") {
        if let Some(end) = out[start..].find("\" }}") {
            let res = out[start + "{{ resource \"".len()..start + end].to_string();
            let full_res = format!("{}{}", path_to_root, res);
            out.replace_range(start..start + end + "\" }}".len(), &full_res);
        } else {
            break;
        }
    }
    out
}

fn replace_if_block(template: &str, var_name: &str, condition: bool) -> String {
    let open_tag = format!("{{{{#if {}}}}}", var_name);
    let close_tag = "{{/if}}";

    let mut out = template.to_string();
    while let Some(start) = out.find(&open_tag) {
        if let Some(end) = out[start..].find(close_tag) {
            let inner = out[start + open_tag.len()..start + end].to_string();
            if condition {
                out.replace_range(start..start + end + close_tag.len(), &inner);
            } else {
                out.replace_range(start..start + end + close_tag.len(), "");
            }
        } else {
            break;
        }
    }
    out
}

fn render_nav_block(template: &str, block_name: &str, link: Option<&str>, path_to_root: &str) -> String {
    let open_tag = format!("{{{{#{}}}}}", block_name);
    let close_tag = format!("{{{{/{}}}}}", block_name);

    let mut out = template.to_string();
    while let Some(start) = out.find(&open_tag) {
        if let Some(end) = out[start..].find(&close_tag) {
            if let Some(l) = link {
                let inner = out[start + open_tag.len()..start + end].to_string();
                let rendered = inner.replace("{{link}}", l).replace("{{ path_to_root }}", path_to_root);
                out.replace_range(start..start + end + close_tag.len(), &rendered);
            } else {
                out.replace_range(start..start + end + close_tag.len(), "");
            }
        } else {
            break;
        }
    }
    out
}

fn remove_handlebars_blocks(template: &str) -> String {
    let mut out = template.to_string();
    for tag in &["{{> head}}", "{{#each additional_css}}", "{{/each}}", "{{#each additional_js}}"] {
        out = out.replace(tag, "");
    }
    out
}
